fn collect() {
    let mut loop_log = []
    let mut guard_log = []
    let mut branch_log = []
    for i in 1..4 {
      defer loop_log.push("pass")
    }
    if true {
      defer branch_log.push("outer")
      if true {
        defer branch_log.push("inner-1")
        defer branch_log.push("inner-2")
      }
    }
    for i in 1..3 {
      if true {
        defer guard_log.push("guard")
      }
    }
    return [loop_log, branch_log, guard_log]
  }
  let r = collect()
  print(r[0])
  print(r[1])
  print(r[2])

