let srv = tcp_listen("127.0.0.1:47311")
match srv {
  Ok(fd) => {
    let cli = tcp_connect("127.0.0.1:47311")
    match cli {
      Ok(cfd) => {
        let acc = tcp_accept(fd)
        match acc {
          Ok(afd) => {
            tcp_send(cfd, "ping")
            let got = tcp_recv(afd, 16)
            match got {
              Ok(text) => { print("echo [{text}]") },
              Err(r) => { print("recv {r}") }
            }
            tcp_close(afd)
          },
          Err(r) => { print("accept {r}") }
        }
        tcp_close(cfd)
      },
      Err(r) => { print("connect {r}") }
    }
    tcp_close(fd)
  },
  Err(r) => { print("listen {r}") }
}

