  try { print([1, "a"].sort_by(fn(x) { return x })) } catch e { print("E " + e) }
  print([3, 1, 2].sort())
  print(["b", "c", "a"].sort())
  print(["bbb", "a", "cc"].sort_by(fn(s) { return len(s) }))
  print([1, 2, 3].min(), [1, 2, 3].max())
  print([].min())
  return 0
}

